From d8dbfb558e4b5b9d71335700d5beeccedff77e82 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:03:51 +0100
Subject: [PATCH] shell/osd: don't show the OSD window while the screen is
 locked

The lock screen shows its own OSD from our signals, but ours was shown
too and kept rendering behind it, which could block plasmashell until
unlock. Now it's hidden while locked and only the signals are emitted.

BUG: 525165
---
 shell/osd.cpp | 25 ++++++++++++++++++++++++-
 shell/osd.h   |  4 ++++
 2 files changed, 28 insertions(+), 1 deletion(-)

diff --git a/shell/osd.cpp b/shell/osd.cpp
index 53c8b03f59..d7d53494c7 100644
--- a/shell/osd.cpp
+++ b/shell/osd.cpp
@@ -12,6 +12,8 @@

 #include <QDBusConnection>
 #include <QDBusMessage>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
 #include <QDBusReply>
 #include <QDebug>
 #include <QQmlComponent>
@@ -37,6 +39,19 @@ Osd::Osd(const KSharedConfig::Ptr &config, ShellCorona *corona)
     , m_configWatcher(KConfigWatcher::create(config)) // will automatically refresh m_osdConfigGroup
 {
     QDBusConnection::sessionBus().registerObject(u"/org/kde/osdService"_s, this, QDBusConnection::ExportAllSlots | QDBusConnection::ExportAllSignals);
+
+    // The lock screen shows its own OSD from our signals; ours would only keep rendering behind it
+    const QString screenSaverService = u"org.freedesktop.ScreenSaver"_s;
+    QDBusConnection::sessionBus().connect(screenSaverService, u"/ScreenSaver"_s, screenSaverService, u"ActiveChanged"_s, this, SLOT(screenLockedChanged(bool)));
+    const QDBusMessage message = QDBusMessage::createMethodCall(screenSaverService, u"/ScreenSaver"_s, screenSaverService, u"GetActive"_s);
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        const QDBusPendingReply<bool> reply = *watcher;
+        if (!reply.isError()) {
+            screenLockedChanged(reply.value());
+        }
+        watcher->deleteLater();
+    });
 }

 Osd::~Osd() = default;
@@ -307,7 +322,7 @@ void Osd::showOsd()
 {
     m_osdTimer->stop();

-    if (!m_osdObject) {
+    if (!m_osdObject || m_screenLocked) {
         return;
     }

@@ -344,4 +359,12 @@ void Osd::hide()
     m_screenBrightnessInfo.clear();
 }

+void Osd::screenLockedChanged(bool locked)
+{
+    m_screenLocked = locked;
+    if (locked) {
+        hide();
+    }
+}
+
 #include "moc_osd.cpp"
diff --git a/shell/osd.h b/shell/osd.h
index bc1071db58..7ee5615d3e 100644
--- a/shell/osd.h
+++ b/shell/osd.h
@@ -50,6 +50,9 @@ Q_SIGNALS:
     void osdProgress(const QString &icon, const int percent, const int maximumPercent, const QString &additionalText);
     void osdText(const QString &icon, const QString &text);

+private Q_SLOTS:
+    void screenLockedChanged(bool locked);
+
 private:
     bool init();

@@ -61,6 +64,7 @@ private:
     std::unique_ptr<QObject> m_osdObject = nullptr;
     QTimer *m_osdTimer = nullptr;
     int m_timeout = 0;
+    bool m_screenLocked = false;

     KConfigGroup m_osdConfigGroup;
     KConfigWatcher::Ptr m_configWatcher;
